"""The load pipeline."""


class TradeReader:
    """Read trades."""

    def read(self, path: str) -> list[str]:
        """Return no rows for path."""
        return []


def make_reader() -> TradeReader:
    """Make a trade reader."""
    return TradeReader()


def run_load(path: str) -> int:
    """Read the trades at path and return their count."""
    reader = make_reader()
    rows = reader.read(path)
    return len(rows)
